import{_ as a,o as t,c as n,a2 as e}from"./chunks/framework.BC3NdntU.js";const u=JSON.parse('{"title":"11.7 提示词工程(下):推理增强(CoT / ToT / ReAct / 自我一致)","description":"","frontmatter":{},"headers":[],"relativePath":"卷十一-AIAgentHarness与提示词工程/11.7-提示词工程下-推理增强.md","filePath":"卷十一-AIAgentHarness与提示词工程/11.7-提示词工程下-推理增强.md","lastUpdated":1788841414000}'),i={name:"卷十一-AIAgentHarness与提示词工程/11.7-提示词工程下-推理增强.md"};function o(r,s,l,p,h,d){return t(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="_11-7-提示词工程-下-推理增强-cot-tot-react-自我一致" tabindex="-1">11.7 提示词工程(下):推理增强(CoT / ToT / ReAct / 自我一致) <a class="header-anchor" href="#_11-7-提示词工程-下-推理增强-cot-tot-react-自我一致" aria-label="Permalink to &quot;11.7 提示词工程(下):推理增强(CoT / ToT / ReAct / 自我一致)&quot;">​</a></h1><blockquote><p>卷:卷十一 · AI Agent Harness 与提示词工程 阅读时间:25min</p></blockquote><hr><h2 id="引言-让模型-想清楚再答" tabindex="-1">引言:让模型&quot;想清楚再答&quot; <a class="header-anchor" href="#引言-让模型-想清楚再答" aria-label="Permalink to &quot;引言:让模型&quot;想清楚再答&quot;&quot;">​</a></h2><p>上半部分解决&quot;说清楚要什么&quot;,这一章解决&quot;让模型答得更对&quot;——核心是诱导模型<strong>显式推理</strong>,而非直接蹦答案。</p><hr><h2 id="一、思维链-cot" tabindex="-1">一、思维链(CoT) <a class="header-anchor" href="#一、思维链-cot" aria-label="Permalink to &quot;一、思维链(CoT)&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">问题:3 个苹果放进 2 个,再拿走 1 个,剩几个?</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">请一步步推理:</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 初始 3 → 2. 放入 2 → 5 → 3. 拿走 1 → 4</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">答案:4 个</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>为什么有效?</strong> 自回归一次只预测&quot;下一个 token&quot;。直接要答案=一步之内算复杂推理;CoT 把推理拆成<strong>一串 token</strong>,每步只做一小步,难度摊薄、中间步骤还能自我纠错。</p><p><strong>触发</strong>:Zero-shot CoT(&quot;让我们一步步思考&quot;)或 Few-shot CoT(示例里展示推理+答案)。</p><hr><h2 id="二、自我一致性-self-consistency" tabindex="-1">二、自我一致性(Self-Consistency) <a class="header-anchor" href="#二、自我一致性-self-consistency" aria-label="Permalink to &quot;二、自我一致性(Self-Consistency)&quot;">​</a></h2><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">answers </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [model.ask(q, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">temperature</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> _ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> range</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">final </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> majority_vote(answers)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><blockquote><p>原理:推理题单次可能想歪,但<strong>多次独立采样</strong>,正确路径更易成为多数。适合有唯一答案的推理题(数学/逻辑)。</p></blockquote><hr><h2 id="三、思维树-tot" tabindex="-1">三、思维树(ToT) <a class="header-anchor" href="#三、思维树-tot" aria-label="Permalink to &quot;三、思维树(ToT)&quot;">​</a></h2><p>不只走一条推理链,而是<strong>同时展开多条、评估、回溯</strong>:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>问题 → 思路A/B/C(并行)→ 各自评估打分 → 剪枝 → 深入最优分支</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><blockquote><p>适合&quot;解空间大、需要搜索&quot;的任务(下棋/规划/谜题)。工程上常简化为&quot;多候选 + 打分选优&quot;。</p></blockquote><hr><h2 id="四、react-推理接工具-回到主线" tabindex="-1">四、ReAct:推理接工具(回到主线) <a class="header-anchor" href="#四、react-推理接工具-回到主线" aria-label="Permalink to &quot;四、ReAct:推理接工具(回到主线)&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Question: 2024 诺贝尔物理奖得主?</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Thought: 不知道最新消息,需要查 → search(&quot;2024 诺贝尔物理奖&quot;)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Observation: 霍普菲尔德、辛顿</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Answer: 约翰·霍普菲尔德 和 杰弗里·辛顿</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><blockquote><p><strong>ReAct 比纯 CoT 强</strong>:纯 CoT 靠脑内知识推,知识截止/记错就错;ReAct 用工具拿事实,把&quot;推理&quot;和&quot;查证&quot;结合——Agent 优于聊天模型的根本(呼应 <a href="/frontend-knowledge-base/卷十一-AIAgentHarness与提示词工程/11.1-从LLM到Agent底层心智.html">11.1</a>)。</p></blockquote><hr><h2 id="五、小结" tabindex="-1">五、小结 <a class="header-anchor" href="#五、小结" aria-label="Permalink to &quot;五、小结&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CoT:显式写推理,摊薄单步难度;自我一致:多次采样+多数投票;ToT:多分支搜索;ReAct:推理接工具</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><hr><h2 id="六、思考题" tabindex="-1">六、思考题 <a class="header-anchor" href="#六、思考题" aria-label="Permalink to &quot;六、思考题&quot;">​</a></h2><p><strong>Q1:CoT 为什么能提升复杂推理正确率?</strong></p><p>把&quot;一步到位算答案&quot;拆成<strong>一串小步 token</strong>,每步只做一小步、难度摊薄;中间步骤写进上下文,模型能<strong>看到并纠正</strong>前面的偏差。自回归的&quot;下一步预测&quot;天然适合逐步展开。</p><p><strong>Q2:什么时候用 ReAct 而非纯 CoT?</strong></p><p>任务<strong>依赖外部事实或需真实动作</strong>时(查最新信息、调工具、执行代码),用 ReAct;纯 CoT 只适合&quot;不依赖外部、纯靠脑内推理&quot;的题(数学/逻辑)。需&quot;碰世界&quot;就必须 ReAct。</p><p><strong>Q3:什么是&quot;自我一致性(Self-Consistency)&quot;?什么时候用?</strong></p><p>同一问题<strong>采样多次、取多数投票</strong>。适合&quot;有唯一正确答案&quot;的推理题(数学/逻辑),多次采样时正确路径更易成多数。</p><p><strong>Q4:ToT 和 CoT 的区别?什么时候用 ToT?</strong></p><p>CoT 走<strong>一条</strong>推理链;ToT <strong>同时展开多条、评估、回溯</strong>,解空间大时搜索最优。适合下棋/规划/谜题;普通推理题 CoT 就够。</p><p><strong>Q5:zero-shot CoT 怎么触发?</strong></p><p>加一句&quot;让我们一步步思考(Let&#39;s think step by step)&quot;,诱导模型显式写出推理步骤,无需示例即可提升复杂推理。</p><p><strong>Q6:ReAct 为什么比纯 CoT 强?</strong></p><p>纯 CoT 只靠脑内知识推,知识过时/记错就错;ReAct 在 Thought 后接 <strong>Action 调工具拿事实</strong>,把&quot;推理&quot;与&quot;查证&quot;结合——事实靠工具锚定,而非靠模型记(呼应 <a href="/frontend-knowledge-base/卷十一-AIAgentHarness与提示词工程/11.1-从LLM到Agent底层心智.html">11.1</a>)。</p><hr><p>📎 参考:Chain-of-Thought 论文(Wei et al.)、Tree of Thoughts 论文、ReAct 论文、Self-Consistency 论文</p>`,42)])])}const k=a(i,[["render",o]]);export{u as __pageData,k as default};
